def calculate_E(a, b, c):
    """Calculates E = ((a+b+c)(ab+bc+ca) + (a+b+c)) / (4abc)"""
    S = a + b + c
    Q = a*b + b*c + c*a
    P = a*b*c
    numerator = S * Q + S
    denominator = 4 * P
    return numerator / denominator

integer_n_values = set()

# Iterate through all combinations (a, b, c) such that a < b < c and a+b+c <= 10
for a in range(1, 10):
    for b in range(a + 1, 10):
        for c in range(b + 1, 11):
            if a + b + c <= 10:
                E = calculate_E(a, b, c)
                # Check if E is an integer
                if E == int(E):
                    integer_n_values.add(int(E))

print("Integer values of n found:", sorted(list(integer_n_values)))

